from openpyxl import load_workbook
from datetime import datetime, timedelta

# Load the workbook
wb = load_workbook("input.xlsx")

# Get the sheets
imported_data_sheet = wb["Imported Data"]
items_older_sheet = wb["Items Older than 30 days"]

# Find the maximum date in column E of 'Imported Data'
max_date = None
for row in imported_data_sheet.iter_rows(min_col=5, max_col=5):
    for cell in row:
        if cell.value:
            date_value = cell.value
            if isinstance(date_value, datetime):
                if max_date is None or date_value > max_date:
                    max_date = date_value

# Calculate the cutoff date (30 days before max date)
cutoff_date = max_date - timedelta(days=30)

# Collect rows where the date in column E is older than cutoff_date
rows_to_copy = []
for row in imported_data_sheet.iter_rows(values_only=True):
    rows_to_copy.append(row)

# Copy the header row and the relevant data rows to 'Items Older than 30 days'
items_older_sheet.delete_rows(1, items_older_sheet.max_row)
for row_idx, row_data in enumerate(rows_to_copy):
    for col_idx, cell_value in enumerate(row_data):
        items_older_sheet.cell(row=row_idx + 1, column=col_idx + 1, value=cell_value)

# Delete column Z in 'Items Older than 30 days'
for row in items_older_sheet.iter_rows():
    for cell in row:
        if cell.column == 26:
            cell.value = None

# Save the workbook
wb.save("output.xlsx")
