from openpyxl import load_workbook

# Load the workbook
wb = load_workbook("input.xlsx")
ws = wb["Statement"]

# Find the first occurrence of 'Invoice No.' in column A
target_row = None
for row in ws.iter_rows(min_col=1, max_col=1):
    for cell in row:
        if cell.value == "Invoice No.":
            target_row = cell.row
            break
    if target_row:
        break

# If 'Invoice No.' is found, delete all rows before it
if target_row:
    for row in range(1, target_row):
        ws.delete_rows(row)

# Write the computed values into the answer range
answer_range = ws["A2:E12"]
for row_idx, row in enumerate(answer_range):
    for col_idx, cell in enumerate(row):
        if row_idx == 0 and col_idx == 0:
            cell.value = "Invoice No."
        elif row_idx == 0 and col_idx == 1:
            cell.value = "Transaction Date"
        elif row_idx == 0 and col_idx == 2:
            cell.value = "Due Date"
        elif row_idx == 0 and col_idx == 3:
            cell.value = "Description"
        elif row_idx == 0 and col_idx == 4:
            cell.value = "Amount"
        else:
            cell.value = None  # Clear any existing values

# Save the result to output.xlsx
wb.save("output.xlsx")
