from openpyxl import load_workbook

# Load the workbook
wb = load_workbook("input.xlsx")

# Access the sheets
sheet1 = wb["Sheet1"]
sheet2 = wb["Sheet2"]

# Get the target date from Sheet1!C5
target_date = sheet1["C5"].value

# Find the column in Sheet2 that matches the target date in row 5
date_row = sheet2[5]
date_col_index = None
for col_idx, cell in enumerate(date_row, start=1):
    if cell.value == target_date:
        date_col_index = col_idx
        break

# If the date is not found, set all to "NEW"
if date_col_index is None:
    for row in sheet1["C6:C31"]:
        for cell in row:
            cell.value = "NEW"
else:
    # Get the values from the corresponding column in Sheet2
    sheet2_col_values = [sheet2.cell(row=row_idx, column=date_col_index).value for row_idx in range(6, 23)]

    # Map items from Sheet1 to their corresponding values in Sheet2
    item_to_value = {}
    for idx, item in enumerate(sheet2[6]):
        if item.value is not None:
            item_to_value[item.value] = sheet2_col_values[idx]

    # Fill in the values in Sheet1!C6:C31
    for row_idx in range(6, 32):
        item = sheet1[f"B{row_idx}"].value
        if item in item_to_value:
            sheet1[f"C{row_idx}"].value = item_to_value[item]
        else:
            sheet1[f"C{row_idx}"].value = "NEW"

# Save the workbook
wb.save("output.xlsx")
